"import csv
from openpyxl import Workbook

INPUT_FILE = "eng_flag_02.csv"
OUTPUT_FILE = "output.xlsx"

LIMITS = {
    "alt_ft": (9000.0, 18000.0),
    "ias_kt": (135.0, 210.0),
    "load_g": (1.05, 2.2),
}
CHANNELS = ["alt_ft", "ias_kt", "load_g"]


def parse_cell(raw):
    """Return float value, or None if the cell is empty / not numeric."""
    if raw is None:
        return None
    s = raw.strip() if isinstance(raw, str) else str(raw).strip()
    if s == "":
        return None
    try:
        return float(s)
    except ValueError:
        return None


def main():
    with open(INPUT_FILE, newline="", encoding="utf-8-sig") as f:
        rows = list(csv.DictReader(f))

    wb = Workbook()

    # ---------------- Sheet DATA ----------------
    ws = wb.active
    ws.title = "DATA"
    ws.append(["time", "alt_ft", "ias_kt", "load_g",
               "status_alt", "status_ias", "status_load"])

    values = {ch: [] for ch in CHANNELS}

    for r in rows:
        # time: copy unchanged (string), empty stays empty (None)
        raw_time = r.get("time")
        if raw_time is None:
            t = None
        else:
            t = raw_time.strip()
            if t == "":
                t = None

        out_row = [t]
        statuses = []

        for ch in CHANNELS:
            v = parse_cell(r.get(ch))
            if v is None:
                # empty cell: write nothing (None keeps the cell empty)
                out_row.append(None)
                statuses.append("MISSING")
            else:
                out_row.append(v)
                values[ch].append(v)
                lo, hi = LIMITS[ch]
                statuses.append("OK" if lo <= v <= hi else "OVER")

        ws.append(out_row + statuses)

    # ---------------- Sheet STATS ----------------
    st = wb.create_sheet("STATS")
    st.append(["channel", "min", "max", "mean"])
    for ch in sorted(CHANNELS):
        vals = values[ch]
        if vals:
            st.append([ch,
                       round(min(vals), 3),
                       round(max(vals), 3),
                       round(sum(vals) / len(vals), 3)])
        else:
            st.append([ch, None, None, None])

    wb.save(OUTPUT_FILE)


if __name__ == "__main__":
    main()"
